W_=326
def mcard(inner,h=None):
    return f'<div class=wrap id=m style="width:{W_}px;box-sizing:border-box;background:#fff;border-radius:20px;overflow:hidden;font-family:Geist,sans-serif">{inner}</div>'
def mtile(n,s=40,bg='#E3F2EE'): return tile(n,s,bg)
def foot(i,t,sub,bg='#E3F2EE'):
    return f'<div style="display:flex;gap:12px;align-items:center;padding:14px 20px;background:#F4F7F6;border-top:1px solid var(--line)">{mtile(i,40,bg)}<div><div style="font-size:15px;font-weight:500">{t}</div><div style="font-size:13px;color:var(--mut);margin-top:1px">{sub}</div></div></div>'
def facts(a,b,c):
    f=lambda l,v:f'<div><div class=mono style="font-size:10.5px;margin-bottom:5px">{l}</div><div style="font-size:16px;font-weight:500">{v}</div></div>'
    return f'<div style="display:grid;grid-template-columns:1.1fr 1fr .9fr;gap:8px;border-top:1px solid var(--line);padding-top:14px">{f("Minimum",a)}{f("Raise",b)}{f("Term",c)}</div>'
m1=mcard(f'<div style="padding:20px 20px 18px;display:flex;flex-direction:column;gap:12px"><div style="display:flex;justify-content:space-between;align-items:center"><span class=mono style="font-size:11.5px">Private equity</span>{chip("Open","g",13)}</div><div style="font-size:21px;font-weight:300;letter-spacing:-.02em;line-height:1.15;white-space:nowrap">Northbridge Growth Partners III</div><div class=bar style="height:6px"><b style="width:64%"></b></div>{facts("USD 250,000","USD 120m","8 years")}</div>'+foot("verify","Identity verified","Reused for every opportunity"))
open('M1.html','w').write(page(m1,W_,400))
m2=mcard(f'<div style="padding:20px 20px 18px"><div class=mono style="font-size:11.5px;margin-bottom:8px">Total commitments</div><div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px"><div style="font-size:38px;font-weight:300;letter-spacing:-.03em;line-height:1">USD 1.05m</div></div><div style="display:flex;align-items:center;gap:20px;border-top:1px solid var(--line);padding-top:16px">{donut([(24,"#0E6B5C"),(19,"#2FB89C"),(57,"#0F1F1D")],112,18)}<div style="display:flex;flex-direction:column;gap:11px;font-size:14.5px"><div style="display:flex;align-items:center;gap:10px"><i style="width:10px;height:10px;border-radius:3px;background:#0F1F1D"></i>Private credit</div><div style="display:flex;align-items:center;gap:10px"><i style="width:10px;height:10px;border-radius:3px;background:#0E6B5C"></i>Private equity</div><div style="display:flex;align-items:center;gap:10px"><i style="width:10px;height:10px;border-radius:3px;background:#2FB89C"></i>Real assets</div></div></div></div>'+foot("sign","2 documents to sign","Northbridge Growth Partners III","#FBF1DC"))
open('M2.html','w').write(page(m2,W_,400))
def mstat(n,l,hi=False): return f'<div style="border-top:3px solid {"var(--teal)" if hi else "var(--line)"};padding-top:10px"><div style="font-size:34px;font-weight:300;letter-spacing:-.03em;line-height:1">{n}</div><div style="font-size:13px;color:var(--mut);margin-top:6px">{l}</div></div>'
def minv(n,k,c,t): return f'<div style="display:flex;align-items:center;gap:12px;padding:11px 0;border-top:1px solid var(--line)"><div class=av style="width:36px;height:36px;font-size:12px">{n.split()[0][0]}{n.split()[-1][0]}</div><div style="flex:1;min-width:0"><div style="font-size:15px;font-weight:500">{n}</div><div style="font-size:12.5px;color:var(--mut)">{k}</div></div>{chip(t,c,12)}</div>'
m3=mcard(f'<div style="padding:20px 20px 10px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px"><span class=mono style="font-size:11.5px">Raise overview</span>{chip("Open","g",13)}</div><div style="font-size:20px;font-weight:300;letter-spacing:-.015em;margin-bottom:16px">Northbridge Growth Partners III</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:14px">{mstat("48","Invited")}{mstat("17","In review")}{mstat("11","Committed",True)}</div>{minv("Alder Family Office","Family office","g","Committed")}{minv("Fenwick Capital","Investment firm","a","In review")}</div>'+foot("adviser","Share with advisers","23 advisers introducing investors"))
open('M3.html','w').write(page(m3,W_,500))
def mcr(n,c,t,k): return f'<div style="display:flex;align-items:center;gap:12px;padding:11px 0;border-top:1px solid var(--line)"><div class=av style="width:38px;height:38px;font-size:13px">{n.split()[0][0]}{n.split()[-1][0]}</div><div style="flex:1;min-width:0"><div style="font-size:15.5px;font-weight:500">{n}</div><div style="font-size:12.5px;color:var(--mut)">{c}</div></div>{chip(t,k,12.5)}</div>'
m4=mcard(f'<div style="padding:20px 20px 8px"><div style="display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:14px"><div><div class=mono style="font-size:11.5px;margin-bottom:6px">Client relationships</div><div style="font-size:28px;font-weight:300;letter-spacing:-.02em;line-height:1">Clients</div></div><span style="font-size:13px;color:var(--mut)">6 clients</span></div>{mcr("Amira Haddad","United Arab Emirates","Verified","g")}{mcr("Daniel Okafor","United Kingdom","Verified","g")}{mcr("Wei Lim","Malaysia","In review","a")}</div>'+foot("onboard","Onboarded once","One profile, every opportunity"))
open('M4.html','w').write(page(m4,W_,500))
def steps(items,cur):
    out=''
    for i,t in enumerate(items):
        on=i<=cur
        out+=f'<div style="flex:1"><div style="height:4px;border-radius:2px;background:{"var(--teal)" if on else "#E3E8E6"};margin-bottom:8px"></div><div style="font-size:12.5px;color:{"#0B1210" if on else "var(--mut)"};font-weight:{500 if i==cur else 400}">{t}</div></div>'
    return f'<div style="display:flex;gap:8px">{out}</div>'
lines=''.join(f'<div style="height:7px;border-radius:4px;background:#E9EEEC;margin-bottom:8px;width:{w}%"></div>' for w in (100,92,97,60))
m5=mcard(f'<div style="padding:20px 20px 18px"><div class=mono style="font-size:11.5px;margin-bottom:8px">Documents</div><div style="font-size:22px;font-weight:300;letter-spacing:-.015em;margin-bottom:14px">Subscription agreement</div><div style="border:1px solid var(--line);border-radius:12px;padding:14px 14px 6px;margin-bottom:12px">{lines}</div><div style="border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin-bottom:14px"><div class=mono style="font-size:10.5px;margin-bottom:6px">Electronic signature</div><div style="font-family:Georgia,serif;font-style:italic;font-size:28px;line-height:1.1">Alder Family Office</div></div>{steps(["Review","Sign","Fund","Confirmed"],1)}</div>'+f'<div style="padding:14px 20px;background:#F4F7F6;border-top:1px solid var(--line)"><span class=btn style="width:100%;justify-content:center;font-size:15px;padding:13px;box-sizing:border-box">Confirm signature</span></div>')
open('M5.html','w').write(page(m5,W_,520))
def opt(t,sub,on): return f'<div style="display:flex;gap:12px;align-items:center;border:1px solid {"var(--teal)" if on else "var(--line)"};background:{"#F1F9F6" if on else "#fff"};border-radius:12px;padding:12px 14px;margin-bottom:10px"><span style="width:18px;height:18px;border-radius:50%;border:2px solid {"var(--teal)" if on else "#B9C4C1"};display:flex;align-items:center;justify-content:center;flex:none">{"<i style=\"width:8px;height:8px;border-radius:50%;background:var(--teal)\"></i>" if on else ""}</span><div><div style="font-size:15px;font-weight:500">{t}</div><div style="font-size:12.5px;color:var(--mut)">{sub}</div></div></div>'
m6=mcard(f'<div style="padding:20px 20px 18px"><div class=mono style="font-size:11.5px;margin-bottom:8px">Step 2 of 4</div><div style="font-size:22px;font-weight:300;letter-spacing:-.015em;margin-bottom:14px">Verify your status</div><div style="margin-bottom:16px">{steps(["Details","Status","Documents","Done"],1)}</div>{opt("Professional investor","Eligible under local rules",True)}{opt("Sophisticated investor","Self-certification and evidence",False)}{opt("Accredited investor","Eligible under local rules",False)}<span class=btn style="width:100%;justify-content:center;font-size:15px;padding:13px;box-sizing:border-box;margin-top:6px">Continue</span></div>')
open('M6.html','w').write(page(m6,W_,520))
